/** Opt-in Routine C diagnostic of natural dictionary checkpoint allocation, without production changes. */
@EnabledIfSystemProperty(named = "rdf4j.lmdb.checkpointProbe", matches = "true")
public class ValueStoreCheckpointInvestigationIT {

	@Test
	void naturalShortKeyCheckpoint() throws Exception {
		int count = Integer.getInteger("rdf4j.lmdb.checkpointProbe.count", 8_000_000);
		int width = Integer.getInteger("rdf4j.lmdb.checkpointProbe.width", 490);
		Path root = Path.of(System.getProperty("rdf4j.lmdb.checkpointProbe.directory",
				"work/lmdb-growth-spill-20261007/native/java-probes"));
		Files.createDirectories(root);
		Path directory = Files.createTempDirectory(root, "w" + width + "-n" + count + "-");
		LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(1_048_576L).setForceSync(false);
		long firstId;
		try (ObservedValueStore values = new ObservedValueStore(directory.toFile(), config)) {
			values.startTransaction(true);
			firstId = values.storeValue(value(0, width));
			for (int i = 1; i < count; i++) {
				values.accepted = i;
				values.storeValue(value(i, width));
			}
			values.accepted = count;
			values.commit();
			verify(values, firstId, count, width);
		}
		try (ObservedValueStore reopened = new ObservedValueStore(directory.toFile(), config)) {
			verify(reopened, firstId, count, width);
		}
		System.out.println("CHECKPOINT_PROBE_SUCCESS count=" + count + " width=" + width + " directory=" + directory);
	}

	private static BNode value(int index, int width) {
		String decimal = Boolean.getBoolean("rdf4j.lmdb.checkpointProbe.random")
				? Long.toUnsignedString(mix(index), 16)
				: Integer.toString(index);
		return SimpleValueFactory.getInstance().createBNode(decimal + "x".repeat(width - 1 - decimal.length()));
	}

	private static long mix(long value) {
		value += 0x9e3779b97f4a7c15L;
		value = (value ^ (value >>> 30)) * 0xbf58476d1ce4e5b9L;
		value = (value ^ (value >>> 27)) * 0x94d049bb133111ebL;
		return value ^ (value >>> 31);
	}

	private static void verify(ValueStore values, long firstId, int count, int width) throws IOException {
		for (int i = 0; i < count; i++) {
			BNode expected = value(i, width);
			long expectedId = firstId + ((long) i << 7);
			assertEquals(expected, values.getValue(expectedId), "ID to value at " + i);
			assertEquals(expectedId, values.getId(expected, false), "value to ID at " + i);
		}
	}

	private static final class ObservedValueStore extends ValueStore implements AutoCloseable {
		private int accepted;
		private int commits;

		private ObservedValueStore(File directory, LmdbStoreConfig config) throws IOException {
			super(directory, config);
		}

		@Override
		int commitWriteTransaction(long transaction) {
			try (MemoryStack stack = stackPush()) {
				MDBStat stat = MDBStat.calloc(stack);
				LmdbUtil.E(mdb_stat(transaction, 1, stat));
				long occupied = LmdbUtil.getNewSize(stat.ms_psize(), transaction, 0L);
				System.out.println("CHECKPOINT_PROBE_BEFORE accepted=" + accepted + " commit=" + ++commits
						+ " mapBytes=" + mapSizeBytes() + " occupiedBytes=" + occupied
						+ " remainingBytes=" + (mapSizeBytes() - occupied));
			} catch (IOException diagnosticFailure) {
				throw new IllegalStateException(diagnosticFailure);
			}
			int result = super.commitWriteTransaction(transaction);
			System.out.println("CHECKPOINT_PROBE_AFTER accepted=" + accepted + " result=" + result
					+ " success=" + (result == MDB_SUCCESS));
			return result;
		}
	}
}
